$s="13.53.133.248";$p="8089";$u="admin";$pw="Salam necesen@123";$uri="https://$s`:$p/services/saved/searches";$auth=[System.Convert]::ToBase64String([System.Text.Encoding]::ASCII.GetBytes("$u`:$pw"));$h=@{Authorization="Basic $auth"};Get-ChildItem "rules\splunk" -Filter "*.yml"|Select-Object -First 1|ForEach-Object{$c=Get-Content $_.FullName -Raw;$id=($c|Select-String "id:\s*`"(.*?)`"").Matches.Groups[1].Value;$name=($c|Select-String "name:\s*`"(.*?)`"").Matches.Groups[1].Value;$search=($c|Select-String "search:\s*>\s*([\s\S]*?)(?=`n[a-z]|\Z)").Matches.Groups[1].Value.Trim();$b=@{name="$id -$name";search=$search;is_scheduled="1"};try{$res=Invoke-RestMethod -Uri $uri -Method Post -Headers$h -Body $b -SkipCertificateCheck;Write-Host "[+] Success: $id" -ForegroundColor Green}catch{if($_.Exception.Response){$reader=New-Object System.IO.StreamReader($_.Exception.Response.GetResponseStream());Write-Host "Splunk Error: $($reader.ReadToEnd())" -ForegroundColor Red}else{Write-Host "Error: $($_.Exception.Message)" -ForegroundColor Red}}}
